function scoreboardUpdating(events) {
  const now = Date.now();
  return events.some(event => {
    const state = (event.competitions?.[0]?.status || event.status)?.type?.state;
    const untilStart = Date.parse(event.date) - now;
    return state === "in" || state === "pre" && untilStart >= -300000 && untilStart <= 120000;
  });
}

function matchListScores(url, liveDay) {
  const previous = cache.get(url)?.d;
  return get(url,!liveDay ? 600000 : !previous || scoreboardUpdating(previous.events || []) ? 2000 : 30000);
}

function matchListStatus(event) {
  return event.competitions?.[0]?.status || event.status;
}

function fresherListScore(current, candidate) {
  const currentStatus = matchListStatus(current);
  const candidateStatus = matchListStatus(candidate);
  if (currentStatus?.type?.state !== "in") return current;
  if (candidateStatus?.type?.state === "post") return candidate;
  if (candidateStatus?.type?.state !== "in") return current;
  return Number(candidateStatus.clock) > Number(currentStatus.clock) ? candidate : current;
}

function enrichLiveListScores(grouped, dates) {
  for (const [league, events] of Object.entries(grouped)) {
    if (!events.some(event => matchListStatus(event)?.type?.state === "in")) continue;
    const candidates = new Map();
    for (const date of dates) {
      const url = `${api(league)}/scoreboard?dates=${date}`;
      const saved = cache.get(url);
      void get(url,4000).catch(() => {});
      if (!saved || Date.now() - saved.t > 8000) continue;
      for (const event of saved.d?.events || []) candidates.set(String(event.id),event);
    }
    grouped[league] = events.map(event => {
      const candidate = candidates.get(String(event.id));
      return candidate ? fresherListScore(event,candidate) : event;
    });
  }
}

