function matchColors(home, away) {
  return {
    home: fxCol(home.color, pcol(home.name)),
    away: fxCol(away.color !== home.color ? away.color : away.alternateColor, pcol(away.name))
  };
}

function matchLinkAction(url, home, away) {
  return `<button class="cbtn txt" data-share-link="${esc(url)}" data-share-title="${esc(`${home} – ${away}`)}">📤 ${t("sh.link")}</button>`;
}

function matchHero({ home, away, date, matchStatus, broadcast, actions = "", liveMatchId, colors = matchColors(home, away) }) {
  const side = team => {
    const identity = `${team.logo}<span>${esc(team.name)}</span>`;
    return `<div class="side">${team.href ? `<a href="${esc(team.href)}">${identity}</a>` : identity}${team.meta || ""}</div>`;
  };
  const { cls, show, txt } = matchStatus;
  const points = value => value == null || value === "" ? "–" : esc(value);
  const score = show ? `${points(home.score)} - ${points(away.score)}`
    : cls === "ppd" || !date ? "– : –" : esc(hm(date));
  const state = cls === "live" ? `<span class="livetag">${t("live")}</span> ${liveHtml(matchStatus)}`
    : cls === "pre" && date ? esc(dshort(date)) : esc(txt);
  const tv = broadcast === undefined ? "<!--tv-->"
    : broadcast ? `<div class="tvtag">📺 ${esc(broadcast)}</div>` : "";
  return `<div class="card hero tchero matchhero${cls === "live" ? " islive" : ""}" style="--hc:${colors.home};--ac:${colors.away}"${liveMatchId ? ` data-fast-score="${esc(liveMatchId)}"` : ""}>
    <div class="row">${side(home)}<div class="mid"><div class="sc">${score}</div>
    <div class="st ${cls}">${state}</div>${tv}</div>${side(away)}</div>
    ${actions ? `<div class="heroact">${actions}</div>` : ""}</div>`;
}

function matchPeriodScore(home, away, periods, colors) {
  const row = (team, side) => `<tr class="${side}"><th scope="row">${team.logo}<span>${esc(team.name)}</span></th>
    ${periods.map((_, index) => `<td>${esc(team.periods[index] ?? "–")}</td>`).join("")}
    <td class="p">${esc(team.score ?? "–")}</td></tr>`;
  return `<div class="card matchperiods" style="--hc:${colors.home};--ac:${colors.away}">
    <h2>${t("score")}</h2><div class="matchperiodscroll"><table class="lines">
      <thead><tr><td></td>${periods.map(label => `<th scope="col">${esc(label)}</th>`).join("")}<th scope="col">${t("total")}</th></tr></thead>
      <tbody>${row(home, "home")}${row(away, "away")}</tbody></table></div></div>`;
}

