const standingLiveBaselines = new Map();

function standingMatch(event) {
  const competition = event.competitions?.[0];
  const matchStatus = competition?.status || event.status;
  const type = matchStatus?.type;
  if (type?.state !== "in" && (type?.state !== "post" || type.completed === false ||
      /POSTPONED|CANCEL|ABANDON|SUSPEND|FORFEIT/i.test(type.name || ""))) return null;
  const [home, away] = sides(competition || {});
  const scores = [home && scoreOf(home), away && scoreOf(away)];
  if (!event.id || !home?.team?.id || !away?.team?.id ||
      !scores.every(score => /^\d+$/.test(String(score)))) return null;
  return {
    id:String(event.id), date:Date.parse(competition.date || event.date), state:type.state,
    h:String(home.team.id), a:String(away.team.id), hs:Number(scores[0]), as:Number(scores[1])
  };
}

function standingData(url, maxAge) {
  const saved = cache.get(url);
  const request = get(url,maxAge);
  if (!saved) return request;
  void request.catch(() => {});
  return saved.d;
}

async function standingMatches(league) {
  const today = new Date();
  const dates = `${ymd(addDays(today,-1))}-${ymd(today)}`;
  const url = `${api(league)}/scoreboard?dates=${dates}&limit=100`;
  const data = await get(url,1500).catch(() => cache.get(url)?.d);
  const now = Date.now();
  return (data?.events || []).map(event => {
    const match = standingMatch(event);
    if (match?.state === "post") return match;
    const summary = cache.get(`${api(league)}/summary?event=${event.id}`);
    if (!summary || now - summary.t > 5000) return match;
    const competition = summary.d?.header?.competitions?.[0];
    const boardClock = Number((event.competitions?.[0]?.status || event.status)?.clock);
    const detailClock = Number(competition?.status?.clock);
    const detail = competition && standingMatch({ ...event, competitions:[competition] });
    if (!detail) return match;
    if (detail.state === "in" && Number.isFinite(boardClock) && Number.isFinite(detailClock) && detailClock < boardClock) return match;
    return detail;
  }).filter(match => match && (match.state === "in" || now - match.date <= 21600000));
}

function standingResult(match, team) {
  const home = match.h === team;
  const gf = home ? match.hs : match.as, ga = home ? match.as : match.hs;
  return { gf, ga, outcome:gf > ga ? "w" : gf === ga ? "d" : "l" };
}

const standingScheduleChecks = new Map();

function missingStandingFinals(league, season, team, official, finals) {
  // Verify an unseen final in the background so it cannot delay other scores.
  const url = `${api(league)}/teams/${team}/schedule?season=${season}`;
  const saved = cache.get(url);
  if (Date.now() >= (standingScheduleChecks.get(url) || 0)) {
    standingScheduleChecks.set(url,Date.now()+30000);
    if (standingScheduleChecks.size > 300) standingScheduleChecks.delete(standingScheduleChecks.keys().next().value);
    void get(url,30000).catch(() => {});
  }
  const data = saved?.d;
  if (!Array.isArray(data?.events)) return [];
  const completed = new Map();
  for (const event of data.events) {
    if (leagueOfEvent(event,league) !== league) continue;
    const match = standingMatch(event);
    if (match?.state === "post" && (match.h === team || match.a === team)) completed.set(match.id,match);
  }
  for (const match of finals) completed.set(match.id,match);
  const ordered = [...completed.values()].filter(match => Number.isFinite(match.date)).sort((a,b) => a.date-b.date);
  if (ordered.length <= official.gp) return [];
  const counted = {w:0,d:0,l:0};
  for (const match of ordered.slice(0,official.gp)) counted[standingResult(match,team).outcome]++;
  if (counted.w !== official.w || counted.d !== official.d || counted.l !== official.l) return [];
  const recent = new Set(finals.map(match => match.id));
  const missing = ordered.slice(official.gp);
  return missing.every(match => recent.has(match.id)) ? missing : [];
}

function projectStandingGroup(league, season, rows, matches) {
  const teams = new Set(rows.map(row => String(row.e.team.id)));
  const groupMatches = matches.filter(match => teams.has(match.h) && teams.has(match.a));
  for (const row of rows) {
    const team = String(row.e.team.id);
    const relevant = groupMatches.filter(match => match.h === team || match.a === team);
    if (!relevant.length) continue;
    const live = relevant.filter(match => match.state === "in");
    const finals = relevant.filter(match => match.state === "post");
    const key = match => `${league}:${season}:${match.id}:${team}`;
    for (const match of live) {
      if (!standingLiveBaselines.has(key(match))) {
        standingLiveBaselines.set(key(match),row.gp);
        if (standingLiveBaselines.size > 300) standingLiveBaselines.delete(standingLiveBaselines.keys().next().value);
      }
    }
    const completed = finals.filter(match => standingLiveBaselines.get(key(match)) === row.gp);
    if (finals.some(match => !standingLiveBaselines.has(key(match)))) {
      for (const match of missingStandingFinals(league,season,team,row,finals)) {
        if (!standingLiveBaselines.has(key(match))) completed.push(match);
      }
    }
    const provisional = [...completed,...live.filter(match => standingLiveBaselines.get(key(match)) === row.gp)];
    for (const match of provisional) {
      const {gf,ga,outcome} = standingResult(match,team);
      const points = outcome === "w" ? 3 : outcome === "d" ? 1 : 0;
      row.gp++;
      row[outcome]++;
      row.gd += gf-ga;
      row.pts += points;
      row.gf += gf;
      row.ga += ga;
      row.delta = (row.delta || 0)+points;
      row.live = {gf,ga,state:match.state};
    }
  }
}

