function openLiveAlertMatch() {
  const [route, league, id] = location.hash.replace(/^#\/?/, "").split("/");
  if ((route === "match" || route === "live") && /^\d+$/.test(id || "") && sportOf(league) === "soccer" && !isTff(league)) {
    return { league, id };
  }
  return null;
}

function watchLiveAlertMatch(league, id, teams = [], beforeKickoff = false) {
  let match = liveAlertMatches.get(id);
  if (!match) {
    match = { league, teams, nextCheck: 0, events: null, score: null };
    liveAlertMatches.set(id, match);
  } else if (teams.length) {
    match.teams = teams;
  }
  if (beforeKickoff && !match.score) {
    match.score = [0, 0];
    match.events ||= new Set();
  }
}

function matchRowGoal(key, homeScore, awayScore, live, match) {
  if (sportOf(match.league) === "soccer" && liveAlertMatches.get(String(match.id))?.score) {
    goalSeen.delete(key);
    const goal = goalAt.get(key);
    return goal?.until > Date.now() ? goal : null;
  }
  return goalCheck(key, homeScore, awayScore, live, match);
}

function watchingLiveAlertMatch(id, match, open = openLiveAlertMatch()) {
  return open?.id === id || match.teams.some(team => isFav(team, match.league));
}

async function discoverLiveAlertFavorites() {
  if (liveAlertDiscovering || Date.now() < liveAlertDiscoveryAt) return;
  const discoveryStartedAt = Date.now();
  liveAlertDiscoveryAt = discoveryStartedAt + 10000;
  const leagues = new Set(favs.filter(favorite =>
    /^\d+$/.test(String(favorite.id)) && sportOf(favorite.league) === "soccer" && !isTff(favorite.league)
  ).map(favorite => favorite.league));
  liveAlertDiscovering = true;
  try {
    await Promise.allSettled([...leagues].map(async league => {
      const data = await get(`${api(league)}/scoreboard`, 4000);
      if (document.hidden) return;
      for (const event of data.events || []) {
        const competition = event.competitions?.[0];
        const state = (competition?.status || event.status)?.type?.state;
        const kickoff = Date.parse(competition?.date || event.date);
        const untilKickoff = kickoff - Date.now();
        const startingSoon = state === "pre" && untilKickoff >= -120000 && untilKickoff <= 120000;
        if (state !== "in" && !startingSoon) continue;
        const teams = (competition?.competitors || []).map(side => side.team?.id).filter(Boolean);
        if (!teams.some(team => isFav(team, league))) continue;

        // A favorite can kick off while its scoreboard request is in flight.
        const kickedOffDuringDiscovery = state === "in" && kickoff >= discoveryStartedAt && untilKickoff <= 0;
        watchLiveAlertMatch(league, String(event.id), teams, startingSoon || kickedOffDuringDiscovery);
      }
    }));
  } finally {
    liveAlertDiscovering = false;
  }
}

function liveAlertNotices(match, data, teams) {
  const events = data.keyEvents?.length ? data.keyEvents : data.header.competitions[0].details;
  if (!Array.isArray(events)) return [];
  const notices = [];
  const seen = match.events || new Set();
  for (const event of events) {
    const type = event.type?.text || "";
    const athlete = event.participants?.[0]?.athlete || event.athletesInvolved?.[0];
    const key = String(event.id ?? event.playId ?? JSON.stringify([
      type, event.clock?.value ?? event.clock?.displayValue, event.team?.id,
      athlete?.id ?? athlete?.displayName
    ]));
    const alreadySeen = seen.has(key);
    seen.add(key);
    if (!match.events || alreadySeen) continue;

    const team = teams.find(side => side.team.id == event.team?.id)?.team;
    const detail = [event.clock?.displayValue, athlete?.displayName, team?.shortDisplayName || team?.displayName]
      .filter(Boolean).join(" · ");
    if (/\b(?:var|video review)\b/i.test(type)) {
      notices.push({ kind: "var", text: ["📺 " + t("np.var"), detail].filter(Boolean).join(" · ") });
    } else if (/\b(?:red|second yellow)(?: card)?\b/i.test(type)) {
      notices.push({ kind: "red", text: ["🟥 " + t("np.red"), detail].filter(Boolean).join(" · ") });
    } else if (/\byellow card\b/i.test(type)) {
      notices.push({ kind: "chime", text: ["🟨 " + t("yellowWord"), detail].filter(Boolean).join(" · ") });
    }
  }
  match.events = seen;
  return notices;
}


function paintFocusedMatchScore(id, competition) {
  const state = competition?.status?.type?.state;
  if (state !== "in" && state !== "post") return;
  const hero = app.querySelector("[data-fast-score]");
  if (hero?.dataset.fastScore !== id) return;
  const scoreNode = hero.querySelector(".sc, .sssc");
  const matchStatus = status(competition.status);
  const teams = sides(competition);
  const scores = teams.map(team => team && scoreOf(team));
  if (!scoreNode || !matchStatus.show || !scores.every(score => /^\d+$/.test(String(score)))) return;
  const separator = scoreNode.classList.contains("sssc") ? "–" : " - ";
  const text = scores.join(separator);
  if (scoreNode.textContent !== text) scoreNode.textContent = text;
  if (!hero.querySelector(".st.live, .ssst.live") && state === "in") hero.dataset.scoreTransition = "";
}

function paintLatestFocusedMatchScore() {
  const open = openLiveAlertMatch();
  if (!open) return;
  const saved = cache.get(`${api(open.league)}/summary?event=${open.id}`);
  if (saved && Date.now() - saved.t <= 5000) {
    paintFocusedMatchScore(open.id,saved.d?.header?.competitions?.[0]);
  }
}

async function checkLiveAlertMatch(id, match, focused) {
  match.pending = true;
  let delay = focused ? 1500 : 3000;
  try {
    const data = await get(`${api(match.league)}/summary?event=${id}`, Math.min(4000, delay - 1000));
    if (document.hidden || liveAlertMatches.get(id) !== match || !watchingLiveAlertMatch(id, match)) return;
    const competition = data.header?.competitions?.[0];
    const type = competition?.status?.type;
    if (!type) throw new Error("Missing match status");
    const [home, away] = sides(competition);
    if (!home?.team || !away?.team) throw new Error("Missing match teams");
    const league = match.league === "all" ? data.header.league?.slug || match.league : match.league;
    match.teams = [home.team.id, away.team.id];
    if (focused && openLiveAlertMatch()?.id === id) paintFocusedMatchScore(id,competition);
    if (type.state === "pre") {
      const untilKickoff = Date.parse(competition.date) - Date.now();
      delay = untilKickoff > 60000 ? Math.min(300000, untilKickoff - 45000) : Math.max(delay, 5000);
      match.score = [0, 0];
      match.events ||= new Set();
      liveAlertNotices(match, data, [home, away]);
      return;
    }
    if (type.state === "post") {
      delay = Infinity;
      if (!match.score) return;
    }

    const scores = [scoreOf(home), scoreOf(away)];
    const notices = liveAlertNotices(match, data, [home, away]);
    if (scores.every(score => /^\d+$/.test(String(score)))) {
      const score = scores.map(Number);
      const previous = match.score;
      match.score = score;
      if (previous && (type.state === "in" || type.state === "post")) {
        if (score.some((value, side) => value < previous[side])) {
          notices.push({ kind: "cancel", text: `↩ ${t("fx.cancel")} · ${score.join("–")}` });
        }
        for (const side of [0, 1]) {
          if (score[side] <= previous[side]) continue;
          const min = competition.status.displayClock || "";
          goalAt.set(`${league}:${id}`, { until: Date.now() + 8000, side });
          goalToast({ league, id, h: home, a: away, side, score: score.join("–"), min });
        }
      }
    }

    if (notices.length) {
      const names = [home, away].map(side => side.team.shortDisplayName || side.team.displayName).join(" – ");
      note(`${names} · ${notices.map(notice => notice.text).join(" / ")}`, "info");
      for (const kind of new Set(notices.map(notice => notice.kind))) kindSound(kind);
    }
  } catch {
    delay = 30000;
  } finally {
    match.pending = false;
    match.nextCheck = Date.now() + delay;
  }
}

function tickLiveAlerts() {
  if (document.hidden) return;
  const open = openLiveAlertMatch();
  if (open) watchLiveAlertMatch(open.league, open.id);
  void discoverLiveAlertFavorites();
  for (const [id, match] of liveAlertMatches) {
    if (!watchingLiveAlertMatch(id, match, open)) {
      liveAlertMatches.delete(id);
    } else if (!match.pending && Date.now() >= match.nextCheck) {
      void checkLiveAlertMatch(id, match, open?.id === id);
    }
  }
}

setInterval(tickLiveAlerts, 500);
addEventListener("hashchange", tickLiveAlerts);
document.addEventListener("visibilitychange", tickLiveAlerts);
tickLiveAlerts();




const livePageRefreshIntervals = { list:3000, live:2000, idle:5000, official:20000 };
let livePageRefreshRoute = "", livePageRefreshedAt = 0, livePageRefreshing = false;
function livePageRefreshMode() {
  const [route,,tab] = location.hash.replace(/^#\/?/,"").split("/");
  if (!route || route === "matches") {
    return document.querySelector("[data-scoreboard-soon]") ? "list" : "";
  }
  if (route !== "table" && (route !== "league" || tab !== "puan")) return "";
  return document.querySelector("[data-live-standings]")?.dataset.liveStandings || "";
}
function tickLivePageRefresh() {
  if (document.hidden || livePageRefreshing) return;
  const delay = livePageRefreshIntervals[livePageRefreshMode()];
  if (!delay) {
    livePageRefreshRoute = "";
    return;
  }
  const route = location.hash || "#/matches";
  const now = Date.now();
  if (livePageRefreshRoute !== route) {
    livePageRefreshRoute = route;
    livePageRefreshedAt = now;
    return;
  }
  if (now - livePageRefreshedAt < delay) return;
  livePageRefreshing = true;
  livePageRefreshedAt = now;
  render(true).finally(() => { livePageRefreshing = false; }).catch(() => {});
}
